import subprocess

def test_pair(c1_before, c1_after, c2_before, c2_after):
    lines = []
    # 5 days before, 5 days after
    for day in range(1, 6):
        for _ in range(c1_before): lines.append(f'127.0.0.1 - - [{day:02d}/Feb/2021:10:11:01 +0000] "GET /p1 HTTP/1.1" 200 100 "-" "-"')
        for _ in range(c2_before): lines.append(f'127.0.0.1 - - [{day:02d}/Feb/2021:10:11:01 +0000] "GET /p2 HTTP/1.1" 200 100 "-" "-"')
    for day in range(6, 11):
        for _ in range(c1_after): lines.append(f'127.0.0.1 - - [{day:02d}/Feb/2021:10:11:01 +0000] "GET /p1 HTTP/1.1" 200 100 "-" "-"')
        for _ in range(c2_after): lines.append(f'127.0.0.1 - - [{day:02d}/Feb/2021:10:11:01 +0000] "GET /p2 HTTP/1.1" 200 100 "-" "-"')

    with open("temp_tp.log", "w") as f:
        f.write("\n".join(lines) + "\n")
    res = subprocess.run(['./executable', 'temp_tp.log', '-c', '-f', 'path', '--color', 'no', '--silent-load', '-a'], capture_output=True, text=True)
    trends = {}
    for l in res.stdout.split('\n'):
        if ('/p1' in l or '/p2' in l) and '│' in l:
            parts = [p.strip() for p in l.split('│')]
            if len(parts) >= 7:
                pname = parts[2]
                tr = parts[6]
                trends[pname] = tr
    return trends

