import subprocess

def test_periods(total_days):
    lines = []
    # Path A: constant 10 hits/day
    # Path B: day 1..N-2: 100/day, last 2 days: 10/day
    for d in range(1, total_days + 1):
        # A
        for _ in range(10):
            lines.append(f'127.0.0.1 - - [{d:02d}/Feb/2021:10:11:01 +0000] "GET /A HTTP/1.1" 200 100 "-" "-"')
        # B
        b_cnt = 10 if d > (total_days - 2) else 100
        for _ in range(b_cnt):
            lines.append(f'127.0.0.1 - - [{d:02d}/Feb/2021:10:11:01 +0000] "GET /B HTTP/1.1" 200 100 "-" "-"')

    with open("temp_per.log", "w") as f:
