import subprocess

# We fix total hits in period 1 (days 1..2) = 1000, total hits in period 2 (days 3..4) = 1000
# Path A has count c1 in period 1, c2 in period 2.
# Path B has count 1000-c1 in period 1, 1000-c2 in period 2.
def test_ratio(c1, c2):
    lines = []
    # Period 1 (days 1..2)
    for d in [1, 2]:
        for _ in range(c1 // 2): lines.append(f'127.0.0.1 - - [{d:02d}/Feb/2021:10:11:01 +0000] "GET /A HTTP/1.1" 200 100 "-" "-"')
