    # Period 2 (days 3..4)
    for d in [3, 4]:
        for _ in range(c2 // 2): lines.append(f'127.0.0.1 - - [{d:02d}/Feb/2021:10:11:01 +0000] "GET /A HTTP/1.1" 200 100 "-" "-"')
        for _ in range((1000 - c2) // 2): lines.append(f'127.0.0.1 - - [{d:02d}/Feb/2021:10:11:01 +0000] "GET /B HTTP/1.1" 200 100 "-" "-"')

    with open("temp_th.log", "w") as f:
        f.write("\n".join(lines) + "\n")
    res = subprocess.run(['./executable', 'temp_th.log', '-c', '-f', 'path', '--color', 'no', '--silent-load', '-a'], capture_output=True, text=True)
    tr_A = ""
    for l in res.stdout.split('\n'):
        if '/A' in l and '│' in l:
            parts = [p.strip() for p in l.split('│')]
            if len(parts) >= 7:
                tr_A = parts[6]
                break
    ratio = c2 / c1 if c1 > 0 else 0
    return ratio, tr_A

c1 = 200
