        timestamp,
        is_resource,
    })
}

fn is_resource_path(path: &str) -> bool {
    let res_exts = [
        ".png", ".jpg", ".jpeg", ".gif", ".ico", ".svg", ".webp", ".css", ".js", ".woff2"
