// Time Filter
#[derive(Debug, Clone)]
pub enum TimeFilter {
    After(u32, String),      // seconds, raw string
    Before(u32, String),     // seconds, raw string
    Range(u32, u32, String), // start_sec, end_sec, raw string
}

fn parse_time_sec(s: &str) -> Result<u32> {
    let parts: Vec<&str> = s.split(':').collect();
    if parts.len() == 2 {
        let h: u32 = parts[0].parse().map_err(|_| anyhow!("TimeFilter(InvalidFormat)"))?;
        let m: u32 = parts[1].parse().map_err(|_| anyhow!("TimeFilter(InvalidFormat)"))?;
        Ok(h * 3600 + m * 60)
    } else if parts.len() == 3 {
        let h: u32 = parts[0].parse().map_err(|_| anyhow!("TimeFilter(InvalidFormat)"))?;
        let m: u32 = parts[1].parse().map_err(|_| anyhow!("TimeFilter(InvalidFormat)"))?;
        let sec: u32 = parts[2].parse().map_err(|_| anyhow!("TimeFilter(InvalidFormat)"))?;
        Ok(h * 3600 + m * 60 + sec)
    } else {
        Err(anyhow!("TimeFilter(InvalidFormat)"))
    }
}

impl TimeFilter {
    pub fn parse(s: &str) -> Result<Self> {
        let s_trim = s.trim();
        if s_trim.starts_with('>') {
            let sec = parse_time_sec(&s_trim[1..])?;
            Ok(TimeFilter::After(sec, s.to_string()))
        } else if s_trim.starts_with('<') {
            let sec = parse_time_sec(&s_trim[1..])?;
            Ok(TimeFilter::Before(sec, s.to_string()))
        } else if s_trim.contains('-') {
            let parts: Vec<&str> = s_trim.split('-').collect();
            if parts.len() != 2 {
                return Err(anyhow!("TimeFilter(InvalidFormat)"));
            }
            let start = parse_time_sec(parts[0])?;
            let mut end = parse_time_sec(parts[1])?;
            if parts[1].split(':').count() == 2 {
                end += 59; // inclusive minute
            }
            Ok(TimeFilter::Range(start, end, s.to_string()))
        } else {
            Err(anyhow!("TimeFilter(InvalidFormat)"))
        }
    }

    pub fn matches(&self, time_str: &str) -> bool {
        let sec = match parse_time_sec(time_str) {
            Ok(s) => s,
            Err(_) => return false,
        };
        match self {
            TimeFilter::After(target, _) => sec > *target,
            TimeFilter::Before(target, _) => sec < *target,
            TimeFilter::Range(start, end, _) => sec >= *start && sec <= *end,
        }
    }

    pub fn raw(&self) -> &str {
        match self {
            TimeFilter::After(_, r) | TimeFilter::Before(_, r) | TimeFilter::Range(_, _, r) => r,
        }
    }
}

// Date Filter
#[derive(Debug, Clone)]
pub enum DateFilter {
    Exact(String, bool),            // date string YYYY/MM/DD, negated
    Month(String, bool),            // YYYY/MM, negated
    Year(String, bool),             // YYYY, negated
    After(i64, String),             // timestamp, raw
    Before(i64, String),            // timestamp, raw
    Range(i64, i64, String),        // start_ts, end_ts, raw
}

impl DateFilter {
    pub fn parse(s: &str) -> Result<Self> {
        let s_trim = s.trim();
        let (raw, negated) = if s_trim.starts_with('!') {
            (&s_trim[1..], true)
        } else {
            (s_trim, false)
        };

        if raw.starts_with('>') {
            let ts = parse_date_ts(&raw[1..], false)?;
            Ok(DateFilter::After(ts, s.to_string()))
        } else if raw.starts_with('<') {
            let ts = parse_date_ts(&raw[1..], true)?;
            Ok(DateFilter::Before(ts, s.to_string()))
        } else if raw.contains('-') {
            let parts: Vec<&str> = raw.split('-').collect();
            if parts.len() != 2 {
                return Err(anyhow!("DateFilter(InvalidFormat)"));
            }
            let start = parse_date_ts(parts[0], true)?;
            let end = parse_date_ts(parts[1], false)?;
            Ok(DateFilter::Range(start, end, s.to_string()))
        } else if raw.split('/').count() == 3 {
            Ok(DateFilter::Exact(raw.to_string(), negated))
        } else if raw.split('/').count() == 2 {
            Ok(DateFilter::Month(raw.to_string(), negated))
        } else if raw.len() == 4 && raw.chars().all(|c| c.is_ascii_digit()) {
            Ok(DateFilter::Year(raw.to_string(), negated))
        } else {
            // maybe MM/DD without year?
            Ok(DateFilter::Exact(raw.to_string(), negated))
        }
    }

    pub fn matches(&self, line: &LogLine) -> bool {
        match self {
            DateFilter::Exact(target, negated) => {
                let m = line.date == *target || line.date.ends_with(target);
                if *negated { !m } else { m }
            }
            DateFilter::Month(target, negated) => {
                let m = line.date.starts_with(target) || line.date.contains(target);
                if *negated { !m } else { m }
            }
            DateFilter::Year(target, negated) => {
                let m = line.date.starts_with(target);
                if *negated { !m } else { m }
            }
            DateFilter::After(target_ts, _) => line.timestamp > *target_ts,
            DateFilter::Before(target_ts, _) => line.timestamp < *target_ts,
            DateFilter::Range(start_ts, end_ts, _) => line.timestamp >= *start_ts && line.timestamp <= *end_ts,
        }
    }

    pub fn raw(&self) -> &str {
        match self {
            DateFilter::Exact(r, _) | DateFilter::Month(r, _) | DateFilter::Year(r, _) => r,
            DateFilter::After(_, r) | DateFilter::Before(_, r) | DateFilter::Range(_, _, r) => r,
        }
    }
}

fn parse_date_ts(s: &str, start_of_day: bool) -> Result<i64> {
    if s.contains('T') {
        let parts: Vec<&str> = s.split('T').collect();
        let date_str = parse_date_part(parts[0])?;
        let time_str = parts[1];
        let full = format!("{} {}", date_str, time_str);
        if time_str.split(':').count() == 2 {
            let full = format!("{}:00", full);
            let dt = chrono::NaiveDateTime::parse_from_str(&full, "%Y/%m/%d %H:%M:%S")
                .map_err(|e| anyhow!("DateTime(IntExpected({:?}))", e))?;
            let mut ts = dt.and_utc().timestamp();
            if !start_of_day {
                ts += 59; // inclusive minute
            }
            Ok(ts)
        } else {
            let dt = chrono::NaiveDateTime::parse_from_str(&full, "%Y/%m/%d %H:%M:%S")
                .map_err(|e| anyhow!("DateTime(IntExpected({:?}))", e))?;
            Ok(dt.and_utc().timestamp())
        }
    } else {
        let date_str = parse_date_part(s)?;
        let time_str = if start_of_day { "00:00:00" } else { "23:59:59" };
        let full = format!("{} {}", date_str, time_str);
        let dt = chrono::NaiveDateTime::parse_from_str(&full, "%Y/%m/%d %H:%M:%S")
            .map_err(|e| anyhow!("DateTime(IntExpected({:?}))", e))?;
        Ok(dt.and_utc().timestamp())
    }
}

fn parse_date_part(s: &str) -> Result<String> {
    let parts: Vec<&str> = s.split('/').collect();
    if parts.len() == 3 {
        let y: u32 = parts[0].parse().map_err(|e| anyhow!("DateTime(IntExpected({:?}))", e))?;
        let m: u32 = parts[1].parse().map_err(|e| anyhow!("DateTime(IntExpected({:?}))", e))?;
        let d: u32 = parts[2].parse().map_err(|e| anyhow!("DateTime(IntExpected({:?}))", e))?;
        Ok(format!("{:04}/{:02}/{:02}", y, m, d))
    } else {
        Err(anyhow!("DateFilter(InvalidFormat)"))
    }
}
