use anyhow::{anyhow, Result};
use regex::Regex;
use crate::log_line::LogLine;

#[derive(Debug, Clone)]
pub enum PatternExpr {
    Term { regex: Regex, negated: bool },
    And(Vec<PatternExpr>),
    Or(Vec<PatternExpr>),
    Not(Box<PatternExpr>),
}

impl PatternExpr {
    pub fn matches(&self, s: &str) -> bool {
        match self {
            PatternExpr::Term { regex, negated } => {
                let m = regex.is_match(s);
                if *negated { !m } else { m }
            }
            PatternExpr::And(exprs) => exprs.iter().all(|e| e.matches(s)),
            PatternExpr::Or(exprs) => exprs.iter().any(|e| e.matches(s)),
            PatternExpr::Not(expr) => !expr.matches(s),
        }
    }

    pub fn parse(pattern: &str) -> Result<Self> {
        let pattern = pattern.trim();
        if pattern.is_empty() {
            return Err(anyhow!("EmptyPattern"));
        }

        // Check if boolean expression with |, &, (, )
        if pattern.contains('|') || pattern.contains('&') || pattern.contains('(') {
            Self::parse_bool_expr(pattern)
        } else if pattern.contains(',') {
            // Comma separated AND list
            let parts: Vec<&str> = pattern.split(',').collect();
            let mut exprs = Vec::new();
            for p in parts {
                let p = p.trim();
                if !p.is_empty() {
                    exprs.push(Self::parse_single_term(p)?);
                }
            }
            Ok(PatternExpr::And(exprs))
        } else {
            Self::parse_single_term(pattern)
        }
    }

    fn parse_single_term(s: &str) -> Result<Self> {
        let s = s.trim();
        let (raw, negated) = if s.starts_with('!') {
            (&s[1..], true)
        } else {
            (s, false)
        };
        let re = Regex::new(raw)?;
        Ok(PatternExpr::Term { regex: re, negated })
    }

    fn parse_bool_expr(s: &str) -> Result<Self> {
        let tokens = tokenize_bool_expr(s)?;
        let mut idx = 0;
        let expr = parse_or_expr(&tokens, &mut idx)?;
        if idx < tokens.len() {
            return Err(anyhow!("InvalidPatternExpression"));
        }
        Ok(expr)
    }
}

#[derive(Debug, Clone, PartialEq)]
enum Token {
    OpOr,
    OpAnd,
    OpNot,
    LParen,
    RParen,
    Term(String),
}

fn tokenize_bool_expr(s: &str) -> Result<Vec<Token>> {
    let mut tokens = Vec::new();
    let mut chars = s.chars().peekable();
    let mut current_term = String::new();

    while let Some(&c) = chars.peek() {
        match c {
            '(' => {
                if !current_term.trim().is_empty() {
                    tokens.push(Token::Term(current_term.trim().to_string()));
                    current_term.clear();
                }
                tokens.push(Token::LParen);
                chars.next();
            }
            ')' => {
                if !current_term.trim().is_empty() {
                    tokens.push(Token::Term(current_term.trim().to_string()));
                    current_term.clear();
                }
                tokens.push(Token::RParen);
                chars.next();
            }
            '|' => {
                if !current_term.trim().is_empty() {
                    tokens.push(Token::Term(current_term.trim().to_string()));
                    current_term.clear();
                }
                tokens.push(Token::OpOr);
                chars.next();
            }
            '&' => {
                if !current_term.trim().is_empty() {
                    tokens.push(Token::Term(current_term.trim().to_string()));
                    current_term.clear();
                }
                tokens.push(Token::OpAnd);
                chars.next();
            }
            '!' => {
                if current_term.trim().is_empty() {
                    tokens.push(Token::OpNot);
                    chars.next();
                } else {
                    current_term.push(c);
                    chars.next();
                }
            }
            _ => {
                current_term.push(c);
                chars.next();
            }
        }
    }
    if !current_term.trim().is_empty() {
        tokens.push(Token::Term(current_term.trim().to_string()));
    }
    Ok(tokens)
}

fn parse_or_expr(tokens: &[Token], idx: &mut usize) -> Result<PatternExpr> {
    let mut exprs = vec![parse_and_expr(tokens, idx)?];
    while *idx < tokens.len() && tokens[*idx] == Token::OpOr {
        *idx += 1;
        exprs.push(parse_and_expr(tokens, idx)?);
    }
    if exprs.len() == 1 {
        Ok(exprs.remove(0))
    } else {
        Ok(PatternExpr::Or(exprs))
    }
}

fn parse_and_expr(tokens: &[Token], idx: &mut usize) -> Result<PatternExpr> {
    let mut exprs = vec![parse_unary_expr(tokens, idx)?];
    while *idx < tokens.len() && tokens[*idx] == Token::OpAnd {
        *idx += 1;
        exprs.push(parse_unary_expr(tokens, idx)?);
    }
    if exprs.len() == 1 {
        Ok(exprs.remove(0))
    } else {
        Ok(PatternExpr::And(exprs))
    }
}

fn parse_unary_expr(tokens: &[Token], idx: &mut usize) -> Result<PatternExpr> {
    if *idx < tokens.len() && tokens[*idx] == Token::OpNot {
        *idx += 1;
        let sub = parse_unary_expr(tokens, idx)?;
        Ok(PatternExpr::Not(Box::new(sub)))
    } else if *idx < tokens.len() && tokens[*idx] == Token::LParen {
        *idx += 1;
        let sub = parse_or_expr(tokens, idx)?;
        if *idx >= tokens.len() || tokens[*idx] != Token::RParen {
            return Err(anyhow!("MissingClosingParen"));
        }
        *idx += 1;
        Ok(sub)
    } else if *idx < tokens.len() {
        if let Token::Term(s) = &tokens[*idx] {
            *idx += 1;
            PatternExpr::parse_single_term(s)
        } else {
            Err(anyhow!("UnexpectedToken"))
        }
    } else {
        Err(anyhow!("UnexpectedEndOfExpression"))
    }
}

// Status Filter
#[derive(Debug, Clone)]
pub enum StatusMatcher {
    Exact(u16, bool),      // status, negated
    Class(u16, bool),      // e.g. 4 for 4xx, negated
    Range(u16, u16, bool), // min, max, negated
}

impl StatusMatcher {
    pub fn matches(&self, status: u16) -> (bool, bool) {
        // Returns (matched_positive, matched_negative)
        match self {
            StatusMatcher::Exact(val, false) => (status == *val, false),
            StatusMatcher::Exact(val, true) => (false, status == *val),
            StatusMatcher::Class(cls, false) => (status / 100 == *cls, false),
            StatusMatcher::Class(cls, true) => (false, status / 100 == *cls),
            StatusMatcher::Range(min, max, false) => (status >= *min && status <= *max, false),
            StatusMatcher::Range(min, max, true) => (false, status >= *min && status <= *max),
        }
    }
}

#[derive(Debug, Clone)]
pub struct StatusFilter {
    pub raw: String,
    pub matchers: Vec<StatusMatcher>,
}

impl StatusFilter {
    pub fn parse(s: &str) -> Result<Self> {
        let mut matchers = Vec::new();
        for token in s.split(',') {
            let token = token.trim();
            if token.is_empty() { continue; }
            let (raw, negated) = if token.starts_with('!') {
                (&token[1..], true)
            } else {
                (token, false)
            };

            if raw.len() == 3 && raw.ends_with("xx") {
                let cls: u16 = raw[..1].parse().map_err(|e| anyhow!("StatusFilter(ParseInt({:?}))", e))?;
                matchers.push(StatusMatcher::Class(cls, negated));
            } else if raw.contains('-') {
                let parts: Vec<&str> = raw.split('-').collect();
                if parts.len() != 2 {
                    return Err(anyhow!("StatusFilter(InvalidFormat)"));
                }
                let min: u16 = parts[0].parse().map_err(|e| anyhow!("StatusFilter(ParseInt({:?}))", e))?;
                let max: u16 = parts[1].parse().map_err(|e| anyhow!("StatusFilter(ParseInt({:?}))", e))?;
                matchers.push(StatusMatcher::Range(min, max, negated));
            } else {
                let val: u16 = raw.parse().map_err(|e| anyhow!("StatusFilter(ParseInt({:?}))", e))?;
                matchers.push(StatusMatcher::Exact(val, negated));
            }
        }
        Ok(StatusFilter { raw: s.to_string(), matchers })
    }

    pub fn matches(&self, status_str: &str) -> bool {
        let status: u16 = match status_str.parse() {
            Ok(v) => v,
            Err(_) => return false,
        };

        let has_positive = self.matchers.iter().any(|m| match m {
            StatusMatcher::Exact(_, false) | StatusMatcher::Class(_, false) | StatusMatcher::Range(_, _, false) => true,
            _ => false,
        });

        let mut matched_positive = !has_positive;
        for m in &self.matchers {
            let (pos, neg) = m.matches(status);
            if neg {
                return false;
            }
            if pos {
                matched_positive = true;
            }
        }
        matched_positive
    }
}

