#[derive(Debug, Clone)]
pub struct TableRow {
    pub value: String,
    pub hits: u64,
    pub bytes: u64,
    pub pct_hits: f64,
    pub pct_bytes: f64,
    pub daily_hits: Vec<u64>,
    pub trend: String,
    pub ratio: f64,
}

#[derive(Debug, Clone)]
pub struct TableData {
    pub field: Field,
    pub title: String,
    pub rows: Vec<TableRow>,
    pub total_hits: u64,
    pub total_bytes: u64,
    pub max_hits: u64,
    pub max_bytes: u64,
    pub dates: Vec<String>,
}

pub fn build_table(
    field: Field,
    lines: &[LogLine],
    all_dates: &[String],
    key_bytes: bool,
    length_level: usize,
    show_changes: bool,
    show_all: bool,
) -> TableData {
    let mut map: HashMap<String, (u64, u64, Vec<u64>)> = HashMap::new();
    let date_to_idx: HashMap<&str, usize> = all_dates.iter().enumerate().map(|(i, d)| (d.as_str(), i)).collect();

    let mut filtered_lines: Vec<&LogLine> = Vec::new();
    for line in lines {
        if field == Field::Path && !show_all && line.is_resource {
            continue;
        }
        filtered_lines.push(line);
    }

    for line in &filtered_lines {
        let val = match field {
            Field::Date => line.date.clone(),
            Field::Time => format!("{:02}", line.time.split(':').next().unwrap_or("00").parse::<u32>().unwrap_or(0)),
            Field::Method => line.method.clone(),
            Field::Status => line.status.clone(),
            Field::Ip => line.remote_addr.clone(),
            Field::Referer => line.referer.clone(),
            Field::Path => line.path.clone(),
        };

        let entry = map.entry(val).or_insert((0, 0, vec![0; all_dates.len()]));
        entry.0 += 1;
        entry.1 += line.bytes_sent;
        if let Some(&idx) = date_to_idx.get(line.date.as_str()) {
            if idx < entry.2.len() {
                entry.2[idx] += 1;
            }
        }
    }

    let total_hits: u64 = filtered_lines.iter().map(|l| 1).sum();
    let total_bytes: u64 = filtered_lines.iter().map(|l| l.bytes_sent).sum();

    let mut max_hits = 0;
    let mut max_bytes = 0;

    // Period calculations for trend
    let n_dates = all_dates.len();
    let (period1_range, period2_range) = if n_dates >= 4 {
        ((n_dates - 4)..=(n_dates - 3), (n_dates - 2)..=(n_dates - 1))
    } else {
        (0..=0, 0..=0)
    };

    let total_p1_hits: u64 = if n_dates >= 4 {
        all_dates[period1_range.clone()].iter().map(|d| {
            filtered_lines.iter().filter(|l| l.date == *d).count() as u64
        }).sum()
    } else { 0 };

    let total_p2_hits: u64 = if n_dates >= 4 {
        all_dates[period2_range.clone()].iter().map(|d| {
            filtered_lines.iter().filter(|l| l.date == *d).count() as u64
        }).sum()
    } else { 0 };

    let mut rows = Vec::new();

    if field == Field::Time {
        // Hour 0..23
        for h in 0..24 {
            let val = format!("{:02}", h);
            let (hits, bytes, daily) = map.get(&val).cloned().unwrap_or((0, 0, vec![0; all_dates.len()]));
            if hits > max_hits { max_hits = hits; }
            if bytes > max_bytes { max_bytes = bytes; }
            rows.push(TableRow {
                value: val,
                hits,
                bytes,
                pct_hits: if total_hits > 0 { hits as f64 / total_hits as f64 * 100.0 } else { 0.0 },
                pct_bytes: if total_bytes > 0 { bytes as f64 / total_bytes as f64 * 100.0 } else { 0.0 },
                daily_hits: daily,
                trend: String::new(),
                ratio: 1.0,
            });
        }
    } else if field == Field::Date {
        for d in all_dates {
            let (hits, bytes, daily) = map.get(d).cloned().unwrap_or((0, 0, vec![0; all_dates.len()]));
            if hits > max_hits { max_hits = hits; }
            if bytes > max_bytes { max_bytes = bytes; }
            rows.push(TableRow {
                value: d.clone(),
                hits,
                bytes,
                pct_hits: if total_hits > 0 { hits as f64 / total_hits as f64 * 100.0 } else { 0.0 },
                pct_bytes: if total_bytes > 0 { bytes as f64 / total_bytes as f64 * 100.0 } else { 0.0 },
                daily_hits: daily,
                trend: String::new(),
                ratio: 1.0,
            });
        }
    } else {
        for (val, (hits, bytes, daily)) in map {
            if hits > max_hits { max_hits = hits; }
            if bytes > max_bytes { max_bytes = bytes; }

            let mut trend = String::new();
            let mut ratio = 1.0;

            if show_changes && n_dates >= 4 && total_p1_hits > 0 && total_p2_hits > 0 {
                let p1_hits: u64 = period1_range.clone().map(|idx| daily[idx]).sum();
                let p2_hits: u64 = period2_range.clone().map(|idx| daily[idx]).sum();

                let s1 = p1_hits as f64 / total_p1_hits as f64;
                let s2 = p2_hits as f64 / total_p2_hits as f64;

                if s1 > 0.0 {
                    ratio = s2 / s1;
                    if ratio >= 3.05 {
                        trend = "➚ ➚".to_string();
                    } else if ratio >= 1.505 {
                        trend = "➚".to_string();
                    } else if ratio <= 0.085 {
                        trend = "➘ ➘ ➘".to_string();
                    } else if ratio <= 0.335 {
                        trend = "➘ ➘".to_string();
                    } else if ratio <= 0.665 {
                        trend = "➘".to_string();
                    }
                }
            }

            rows.push(TableRow {
                value: val,
                hits,
                bytes,
                pct_hits: if total_hits > 0 { hits as f64 / total_hits as f64 * 100.0 } else { 0.0 },
                pct_bytes: if total_bytes > 0 { bytes as f64 / total_bytes as f64 * 100.0 } else { 0.0 },
                daily_hits: daily,
                trend,
                ratio,
            });
        }

        // Sort rows
        if key_bytes {
            rows.sort_by(|a, b| b.bytes.cmp(&a.bytes).then_with(|| a.value.cmp(&b.value)));
        } else {
            rows.sort_by(|a, b| b.hits.cmp(&a.hits).then_with(|| a.value.cmp(&b.value)));
        }

        // Truncate length
        let max_rows = if length_level == 0 { 10 } else { length_level * 50 };
        if rows.len() > max_rows {
            rows.truncate(max_rows);
        }
    }

    let title = match field {
        Field::Date => String::new(),
        Field::Time => String::new(),
        Field::Method => format!("{} methods. ", rows.len()),
        Field::Status => format!("{} HTTP status codes. ", rows.len()),
        Field::Ip => format!("{} remote IP addresses. ", rows.len()),
        Field::Referer => format!("{} referrers. ", rows.len()),
        Field::Path => if show_all {
            format!("{} paths. ", rows.len())
        } else {
            format!("{} paths (excluding resources like images, css, \netc.). ", rows.len())
        },
    };

    TableData {
        field,
        title,
        rows,
        total_hits,
        total_bytes,
        max_hits,
        max_bytes,
        dates: all_dates.to_vec(),
    }
}
EOF"}

