    let mut max_bytes = 0;

    // Period calculations for trend
    let n_dates = all_dates.len();
    let (period1_range, period2_range) = if n_dates >= 4 {
        ((n_dates - 4)..=(n_dates - 3), (n_dates - 2)..=(n_dates - 1))
    } else {
        (0..=0, 0..=0)
    };

    let total_p1_hits: u64 = if n_dates >= 4 {
        all_dates[period1_range.clone()].iter().map(|d| {
            filtered_lines.iter().filter(|l| l.date == *d).count() as u64
        }).sum()
    } else { 0 };

    let total_p2_hits: u64 = if n_dates >= 4 {
        all_dates[period2_range.clone()].iter().map(|d| {
            filtered_lines.iter().filter(|l| l.date == *d).count() as u64
        }).sum()
    } else { 0 };

    let mut rows = Vec::new();

    if field == Field::Time {
        // Hour 0..23
        for h in 0..24 {
            let val = format!("{:02}", h);
            let (hits, bytes, daily) = map.get(&val).cloned().unwrap_or((0, 0, vec![0; all_dates.len()]));
            if hits > max_hits { max_hits = hits; }
            if bytes > max_bytes { max_bytes = bytes; }
            rows.push(TableRow {
                value: val,
                hits,
                bytes,
                pct_hits: if total_hits > 0 { hits as f64 / total_hits as f64 * 100.0 } else { 0.0 },
                pct_bytes: if total_bytes > 0 { bytes as f64 / total_bytes as f64 * 100.0 } else { 0.0 },
                daily_hits: daily,
                trend: String::new(),
                ratio: 1.0,
            });
        }
    } else if field == Field::Date {
        for d in all_dates {
            let (hits, bytes, daily) = map.get(d).cloned().unwrap_or((0, 0, vec![0; all_dates.len()]));
            if hits > max_hits { max_hits = hits; }
            if bytes > max_bytes { max_bytes = bytes; }
            rows.push(TableRow {
                value: d.clone(),
                hits,
                bytes,
                pct_hits: if total_hits > 0 { hits as f64 / total_hits as f64 * 100.0 } else { 0.0 },
                pct_bytes: if total_bytes > 0 { bytes as f64 / total_bytes as f64 * 100.0 } else { 0.0 },
                daily_hits: daily,
                trend: String::new(),
                ratio: 1.0,
            });
        }
    } else {
        for (val, (hits, bytes, daily)) in map {
            if hits > max_hits { max_hits = hits; }
            if bytes > max_bytes { max_bytes = bytes; }

            let mut trend = String::new();
            let mut ratio = 1.0;

            if show_changes && n_dates >= 4 && total_p1_hits > 0 && total_p2_hits > 0 {
                let p1_hits: u64 = period1_range.clone().map(|idx| daily[idx]).sum();
                let p2_hits: u64 = period2_range.clone().map(|idx| daily[idx]).sum();

                let s1 = p1_hits as f64 / total_p1_hits as f64;
                let s2 = p2_hits as f64 / total_p2_hits as f64;

                if s1 > 0.0 {
                    ratio = s2 / s1;
                    if ratio >= 3.05 {
                        trend = "➚ ➚".to_string();
                    } else if ratio >= 1.505 {
                        trend = "➚".to_string();
                    } else if ratio <= 0.085 {
                        trend = "➘ ➘ ➘".to_string();
                    } else if ratio <= 0.335 {
                        trend = "➘ ➘".to_string();
                    } else if ratio <= 0.665 {
                        trend = "➘".to_string();
                    }
                }
            }

            rows.push(TableRow {
                value: val,
                hits,
                bytes,
                pct_hits: if total_hits > 0 { hits as f64 / total_hits as f64 * 100.0 } else { 0.0 },
                pct_bytes: if total_bytes > 0 { bytes as f64 / total_bytes as f64 * 100.0 } else { 0.0 },
                daily_hits: daily,
