use std::io::{self, Write};
use crate::log_line::LogLine;
use crate::table::{TableData, Field, TableRow};

pub fn fmt_num(n: u64) -> String {
    let s = n.to_string();
    let mut result = String::new();
    let len = s.len();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    result
}

pub fn fmt_bytes(b: u64) -> String {
    if b < 10_000 {
        format!("{}", b)
    } else if b < 1_000_000 {
        format!("{}K", b / 1000)
    } else if b < 10_000_000 {
        format!("{:.1}M", b as f64 / 1_000_000.0)
    } else if b < 1_000_000_000 {
        format!("{}M", b / 1_000_000)
    } else if b < 10_000_000_000 {
        format!("{:.1}G", b as f64 / 1_000_000_000.0)
    } else if b < 1_000_000_000_000 {
        format!("{}G", b / 1_000_000_000)
    } else if b < 10_000_000_000_000 {
        format!("{:.1}T", b as f64 / 1_000_000_000_000.0)
    } else {
        format!("{}T", b / 1_000_000_000_000)
    }
}

pub fn render_bar(val: u64, max_val: u64, width: usize) -> String {
    if max_val == 0 || val == 0 {
        return " ".repeat(width);
    }
    let frac = (width as f64) * (val as f64) / (max_val as f64);
    let full = frac.floor() as usize;
    let rem = frac - (full as f64);
    let eighths = (rem * 8.0).round() as usize;

    let blocks = ["", "▏", "▎", "▍", "▌", "▋", "▊", "▉", "█"];
    let mut s = "█".repeat(full.min(width));
    if full < width && eighths > 0 {
        let idx = eighths.min(8);
        if idx == 8 {
            s.push('█');
        } else {
            s.push_str(blocks[idx]);
        }
    }
    let cur_len = full + if eighths > 0 && eighths < 8 { 1 } else if eighths == 8 { 1 } else { 0 };
    if cur_len < width {
        s.push_str(&" ".repeat(width - cur_len));
    }
    s
}

