use std::fs::File;
use std::io::{BufRead, BufReader, Read};
use std::path::{Path, PathBuf};
use flate2::read::GzDecoder;
use regex::Regex;
use serde::Serialize;
use anyhow::{Result, anyhow};

#[derive(Debug, Clone, Serialize)]
pub struct LogLine {
    pub date: String,          // YYYY/MM/DD
    pub time: String,          // HH:MM:SS
    pub remote_addr: String,   // IP address
    pub method: String,        // GET, POST, etc. or "other" or "none"
    pub path: String,          // /path without query string
    pub status: String,        // 200, 404, etc.
    pub bytes_sent: u64,       // bytes
    pub referer: String,       // referer
    #[serde(skip)]
    pub raw_line: String,      // original log line
    #[serde(skip)]
    pub timestamp: i64,        // epoch timestamp for sorting/date math
    #[serde(skip)]
    pub is_resource: bool,     // resource path flag
}

fn month_to_num(m: &str) -> &'static str {
    match m {
        "Jan" => "01",
        "Feb" => "02",
        "Mar" => "03",
        "Apr" => "04",
        "May" => "05",
        "Jun" => "06",
        "Jul" => "07",
        "Aug" => "08",
        "Sep" => "09",
        "Oct" => "10",
        "Nov" => "11",
        "Dec" => "12",
        _ => "01",
    }
}

pub fn get_log_regex() -> Regex {
    Regex::new(r#"^(\S+) \S+ \S+ \[([\w/:]+) [^\]]+\] "([^"]*)" (\d{3}) (\d+|-)(?: "([^"]*)" "([^"]*)")?"#).unwrap()
}

pub fn parse_log_line(line: &str, re: &Regex) -> Option<LogLine> {
    let caps = re.captures(line)?;
    let ip = caps.get(1)?.as_str().to_string();
    let time_str = caps.get(2)?.as_str(); // e.g. 15/Feb/2021:10:11:12
    let request_str = caps.get(3)?.as_str();
    let status = caps.get(4)?.as_str().to_string();
    let bytes_str = caps.get(5)?.as_str();
    let referer = caps.get(6).map_or("-", |m| m.as_str()).to_string();

    // Parse date and time
    // format: DD/Mon/YYYY:HH:MM:SS
    let parts: Vec<&str> = time_str.split(':').collect();
    if parts.len() < 4 {
        return None;
    }
    let date_parts: Vec<&str> = parts[0].split('/').collect();
    if date_parts.len() < 3 {
        return None;
    }
    let day: u32 = date_parts[0].parse().ok()?;
    let month = month_to_num(date_parts[1]);
    let year: u32 = date_parts[2].parse().ok()?;

    let hour: u32 = parts[1].parse().ok()?;
    let min: u32 = parts[2].parse().ok()?;
    let sec: u32 = parts[3].parse().ok()?;

    let date = format!("{:04}/{}/{:02}", year, month, day);
    let time = format!("{:02}:{:02}:{:02}", hour, min, sec);

    let month_num: u32 = month.parse().unwrap_or(1);
    let chrono_date = chrono::NaiveDate::from_ymd_opt(year as i32, month_num, day)?;
    let chrono_time = chrono::NaiveTime::from_hms_opt(hour, min, sec)?;
    let dt = chrono::NaiveDateTime::new(chrono_date, chrono_time);
    let timestamp = dt.and_utc().timestamp();

    // Parse request
    let req_parts: Vec<&str> = request_str.split_whitespace().collect();
    let (method, raw_path) = if req_parts.len() == 2 || req_parts.len() == 3 {
        let m = req_parts[0];
        let method = match m {
            "GET" | "POST" | "PUT" | "DELETE" | "HEAD" | "OPTIONS" | "PATCH" | "CONNECT" | "TRACE" => m.to_string(),
            _ => "other".to_string(),
        };
        (method, req_parts[1])
    } else {
        ("none".to_string(), request_str)
    };

    let path = match raw_path.find('?') {
        Some(idx) => &raw_path[..idx],
        None => raw_path,
    }.to_string();

    let bytes_sent = if bytes_str == "-" {
        0
    } else {
        bytes_str.parse().unwrap_or(0)
    };

    let is_resource = is_resource_path(&path);

    Some(LogLine {
        date,
        time,
        remote_addr: ip,
        method,
        path,
        status,
        bytes_sent,
        referer,
        raw_line: line.to_string(),
        timestamp,
        is_resource,
    })
}

fn is_resource_path(path: &str) -> bool {
    let res_exts = [
        ".png", ".jpg", ".jpeg", ".gif", ".ico", ".svg", ".webp", ".css", ".js", ".woff2"
    ];
    for ext in &res_exts {
        if path.ends_with(ext) {
            return true;
        }
    }
    false
}

pub fn collect_files(paths: &[PathBuf], no_name_check: bool) -> Result<Vec<PathBuf>> {
    let mut files = Vec::new();

    if paths.is_empty() {
        let default_path = PathBuf::from("/var/log/nginx");
        if !default_path.exists() {
            eprintln!("No nginx log found at default location, do you have nginx set up?");
            eprintln!("If necessary, provide the path to the log file(s) as argument.");
            eprintln!("More information with 'rhit --help'.");
            return Err(anyhow!("PathNotFound(\"/var/log/nginx\")"));
        }
        collect_from_path(&default_path, no_name_check, &mut files)?;
    } else {
        for p in paths {
            if !p.exists() {
                return Err(anyhow!("PathNotFound({:?})", p.to_string_lossy()));
            }
            if p.is_file() {
                files.push(p.clone());
            } else if p.is_dir() {
                collect_from_path(p, no_name_check, &mut files)?;
            }
        }
    }

    if files.is_empty() {
        return Err(anyhow!("NoLogFileFound"));
    }

    Ok(files)
}

fn collect_from_path(dir: &Path, no_name_check: bool, files: &mut Vec<PathBuf>) -> Result<()> {
    if dir.is_file() {
        if no_name_check || dir.file_name().and_then(|n| n.to_str()).map_or(false, |s| s.contains("access.log")) {
            files.push(dir.to_path_buf());
        }
        return Ok(());
    }

    let entries = std::fs::read_dir(dir)?;
    for entry in entries {
        let entry = entry?;
        let path = entry.path();
        if path.is_dir() {
            collect_from_path(&path, no_name_check, files)?;
        } else if path.is_file() {
            if no_name_check || path.file_name().and_then(|n| n.to_str()).map_or(false, |s| s.contains("access.log")) {
                files.push(path);
            }
        }
    }
    Ok(())
}

pub fn read_log_file(path: &Path) -> Result<Vec<LogLine>> {
    let file = File::open(path)?;
    let mut reader: Box<dyn BufRead> = if path.extension().and_then(|s| s.to_str()) == Some("gz") {
        Box::new(BufReader::new(GzDecoder::new(file)))
    } else {
        // Also check magic bytes 0x1f, 0x8b
        let mut buf_reader = BufReader::new(file);
        let mut header = [0u8; 2];
        let bytes_read = buf_reader.read(&mut header).unwrap_or(0);
        let file = File::open(path)?;
        if bytes_read == 2 && header == [0x1f, 0x8b] {
            Box::new(BufReader::new(GzDecoder::new(file)))
        } else {
            Box::new(BufReader::new(file))
        }
    };

    let re = get_log_regex();
    let mut lines = Vec::new();
    let mut line_buf = String::new();

    while reader.read_line(&mut line_buf)? > 0 {
        let trimmed = line_buf.trim_end();
        if !trimmed.is_empty() {
            if let Some(log_line) = parse_log_line(trimmed, &re) {
                lines.push(log_line);
            }
        }
        line_buf.clear();
    }

    Ok(lines)
}
EOF"}

