{"command":"cat << 'EOF' > src/main.rs
mod args;
use std::process::exit;

mod log_line;
mod filter;
mod table;
mod output;

use args::parse_args;
use log_line::{collect_files, read_log_file, LogLine};
use filter::{DateFilter, TimeFilter, MethodFilter, StatusFilter, PatternExpr};
use table::{parse_fields, build_table};
use output::{print_json, print_csv, print_raw, print_tables};

fn main() {
    let args = parse_args();

    if args.version {
        println!("rhit 2.0.4");
        exit(0);
    }

    if args.help {
        print!("{}", args::HELP_TEXT);
        exit(0);
    }

    let stdout_is_tty = unsafe { libc::isatty(1) == 1 };
    let use_color = match args.color.as_str() {
        "yes" => true,
        "no" => false,
        _ => stdout_is_tty,
    };

    let is_silent = args.silent_load || !stdout_is_tty;

    let file_paths = match collect_files(&args.files, args.no_name_check) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("Error: {}", e);
            exit(1);
        }
    };

    if !is_silent {
        let count = file_paths.len();
        if count == 1 {
            eprintln!("I've read 1 file in \"{}\"", file_paths[0].to_string_lossy());
        } else {
            eprintln!("I've read {} files", count);
        }
    }

    let mut all_lines: Vec<LogLine> = Vec::new();
    for path in &file_paths {
        match read_log_file(path) {
            Ok(lines) => all_lines.extend(lines),
            Err(e) => {
                eprintln!("Error: {}", e);
                exit(1);
            }
        }
    }

    if all_lines.is_empty() {
        eprintln!("Error: NoLogFileFound");
        exit(1);
    }

    // Sort all lines by timestamp
    all_lines.sort_by_key(|l| l.timestamp);

    let total_unfiltered_hits = all_lines.len() as u64;
    let total_unfiltered_bytes: u64 = all_lines.iter().map(|l| l.bytes_sent).sum();

    // Unique dates
    let mut all_dates: Vec<String> = Vec::new();
    for l in &all_lines {
        if !all_dates.contains(&l.date) {
            all_dates.push(l.date.clone());
        }
    }

    let min_date = all_dates.first().cloned().unwrap_or_default();
    let max_date = all_dates.last().cloned().unwrap_or_default();

    // Parse filters
    let date_filter = match args.date.as_deref() {
        Some(s) => match DateFilter::parse(s) {
            Ok(f) => Some(f),
            Err(e) => {
                eprintln!("Error: {}", e);
                exit(1);
            }
        },
        None => None,
    };

    let time_filter = match args.time.as_deref() {
        Some(s) => match TimeFilter::parse(s) {
            Ok(f) => Some(f),
            Err(e) => {
                eprintln!("Error: {}", e);
                exit(1);
            }
        },
        None => None,
    };

    let method_filter = match args.method.as_deref() {
        Some(s) => match MethodFilter::parse(s) {
            Ok(f) => Some(f),
            Err(e) => {
                eprintln!("Error: {}", e);
                exit(1);
            }
        },
        None => None,
    };

    let status_filter = match args.status.as_deref() {
        Some(s) => match StatusFilter::parse(s) {
            Ok(f) => Some(f),
            Err(e) => {
                eprintln!("Error: {}", e);
                exit(1);
            }
        },
        None => None,
    };

    let ip_filter = match args.ip.as_deref() {
        Some(s) => match PatternExpr::parse(s) {
            Ok(f) => Some((s, f)),
            Err(e) => {
                eprintln!("Error: {}", e);
                exit(1);
            }
        },
        None => None,
    };

    let referer_filter = match args.referer.as_deref() {
        Some(s) => match PatternExpr::parse(s) {
            Ok(f) => Some((s, f)),
            Err(e) => {
                eprintln!("Error: {}", e);
                exit(1);
            }
        },
        None => None,
    };

    let path_filter = match args.path.as_deref() {
        Some(s) => match PatternExpr::parse(s) {
            Ok(f) => Some((s, f)),
            Err(e) => {
                eprintln!("Error: {}", e);
                exit(1);
            }
        },
        None => None,
    };

    // Apply filters and track summaries
    let mut current_lines = all_lines;
    let mut filter_summaries: Vec<(String, String, f64, u64, u64)> = Vec::new();

    // 1. Date filter
    if let Some(f) = &date_filter {
        let before_count = current_lines.len();
        current_lines.retain(|l| f.matches(l));
        let removed = before_count - current_lines.len();
        let removed_pct = if total_unfiltered_hits > 0 {
            removed as f64 / total_unfiltered_hits as f64 * 100.0
        } else { 0.0 };
        let kept_hits = current_lines.len() as u64;
        let kept_bytes: u64 = current_lines.iter().map(|l| l.bytes_sent).sum();
        filter_summaries.push(("date".to_string(), f.raw().to_string(), removed_pct, kept_hits, kept_bytes));
    }

    // 2. Time filter
    if let Some(f) = &time_filter {
        let before_count = current_lines.len();
        current_lines.retain(|l| f.matches(&l.time));
        let removed = before_count - current_lines.len();
        let removed_pct = if total_unfiltered_hits > 0 {
            removed as f64 / total_unfiltered_hits as f64 * 100.0
        } else { 0.0 };
        let kept_hits = current_lines.len() as u64;
        let kept_bytes: u64 = current_lines.iter().map(|l| l.bytes_sent).sum();
        filter_summaries.push(("time".to_string(), f.raw().to_string(), removed_pct, kept_hits, kept_bytes));
    }

    // 3. Method filter
    if let Some(f) = &method_filter {
        let before_count = current_lines.len();
        current_lines.retain(|l| f.matches(&l.method));
        let removed = before_count - current_lines.len();
        let removed_pct = if total_unfiltered_hits > 0 {
            removed as f64 / total_unfiltered_hits as f64 * 100.0
        } else { 0.0 };
        let kept_hits = current_lines.len() as u64;
        let kept_bytes: u64 = current_lines.iter().map(|l| l.bytes_sent).sum();
        filter_summaries.push(("method".to_string(), f.raw.clone(), removed_pct, kept_hits, kept_bytes));
    }

    // 4. Status filter
    if let Some(f) = &status_filter {
        let before_count = current_lines.len();
        current_lines.retain(|l| f.matches(&l.status));
        let removed = before_count - current_lines.len();
        let removed_pct = if total_unfiltered_hits > 0 {
            removed as f64 / total_unfiltered_hits as f64 * 100.0
        } else { 0.0 };
        let kept_hits = current_lines.len() as u64;
        let kept_bytes: u64 = current_lines.iter().map(|l| l.bytes_sent).sum();
        filter_summaries.push(("status".to_string(), f.raw.clone(), removed_pct, kept_hits, kept_bytes));
    }

    // 5. IP filter
    if let Some((raw, expr)) = &ip_filter {
        let before_count = current_lines.len();
        current_lines.retain(|l| expr.matches(&l.remote_addr));
        let removed = before_count - current_lines.len();
        let removed_pct = if total_unfiltered_hits > 0 {
            removed as f64 / total_unfiltered_hits as f64 * 100.0
        } else { 0.0 };
        let kept_hits = current_lines.len() as u64;
        let kept_bytes: u64 = current_lines.iter().map(|l| l.bytes_sent).sum();
        filter_summaries.push(("remote address".to_string(), raw.to_string(), removed_pct, kept_hits, kept_bytes));
    }

    // 6. Referer filter
    if let Some((raw, expr)) = &referer_filter {
        let before_count = current_lines.len();
        current_lines.retain(|l| expr.matches(&l.referer));
        let removed = before_count - current_lines.len();
        let removed_pct = if total_unfiltered_hits > 0 {
            removed as f64 / total_unfiltered_hits as f64 * 100.0
        } else { 0.0 };
        let kept_hits = current_lines.len() as u64;
        let kept_bytes: u64 = current_lines.iter().map(|l| l.bytes_sent).sum();
        filter_summaries.push(("referer".to_string(), raw.to_string(), removed_pct, kept_hits, kept_bytes));
    }

    // 7. Path filter
    if let Some((raw, expr)) = &path_filter {
        let before_count = current_lines.len();
        current_lines.retain(|l| expr.matches(&l.path));
        let removed = before_count - current_lines.len();
        let removed_pct = if total_unfiltered_hits > 0 {
            removed as f64 / total_unfiltered_hits as f64 * 100.0
        } else { 0.0 };
        let kept_hits = current_lines.len() as u64;
        let kept_bytes: u64 = current_lines.iter().map(|l| l.bytes_sent).sum();
        filter_summaries.push(("path".to_string(), raw.to_string(), removed_pct, kept_hits, kept_bytes));
    }

    let key_bytes = args.key == "bytes" || args.key == "b";

    let output_format = args.output.as_str();
    if output_format == "json" || output_format == "j" {
        print_json(&current_lines);
        return;
    }
    if output_format == "csv" || output_format == "c" {
        print_csv(&current_lines);
        return;
    }
    if output_format == "raw" || output_format == "r" {
        print_raw(&current_lines);
        return;
    }

    // Default: tables
    let fields = parse_fields(args.fields.as_deref());
    let mut tables = Vec::new();

    for field in fields {
        let t = build_table(
            field,
            &current_lines,
            &all_dates,
            key_bytes,
            args.length,
            args.changes,
            args.all,
        );
        tables.push(t);
    }

    print_tables(
        &tables,
        total_unfiltered_hits,
        total_unfiltered_bytes,
        &min_date,
        &max_date,
        &filter_summaries,
        use_color,
        key_bytes,
        args.changes,
    );
}
EOF"}

