use crate::log_line::LogLine;
use crate::table::{TableData, Field};

pub fn fmt_num(n: u64) -> String {
    let s = n.to_string();
    let mut result = String::new();
    let len = s.len();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    result
}

pub fn fmt_bytes(b: u64) -> String {
    if b < 10_000 {
        format!("{}", b)
    } else if b < 1_000_000 {
        format!("{}K", b / 1000)
    } else if b < 10_000_000 {
        format!("{:.1}M", b as f64 / 1_000_000.0)
    } else if b < 1_000_000_000 {
        format!("{}M", b / 1_000_000)
    } else if b < 10_000_000_000 {
        format!("{:.1}G", b as f64 / 1_000_000_000.0)
    } else if b < 1_000_000_000_000 {
        format!("{}G", b / 1_000_000_000)
    } else if b < 10_000_000_000_000 {
        format!("{:.1}T", b as f64 / 1_000_000_000_000.0)
    } else {
        format!("{}T", b / 1_000_000_000_000)
    }
}

pub fn render_bar(val: u64, max_val: u64, width: usize) -> String {
    if max_val == 0 || val == 0 {
        return " ".repeat(width);
    }
    let frac = (width as f64) * (val as f64) / (max_val as f64);
    let full = frac.floor() as usize;
    let rem = frac - (full as f64);
    let eighths = (rem * 8.0).round() as usize;

    let blocks = ["", "▏", "▎", "▍", "▌", "▋", "▊", "▉", "█"];
    let mut s = "█".repeat(full.min(width));
    if full < width && eighths > 0 {
        let idx = eighths.min(8);
        if idx == 8 {
            s.push('█');
        } else {
            s.push_str(blocks[idx]);
        }
    }
    let cur_len = full + if eighths > 0 { 1 } else { 0 };
    if cur_len < width {
        s.push_str(&" ".repeat(width - cur_len));
    }
    s
}

pub fn print_json(lines: &[LogLine]) {
    let json_str = serde_json::to_string_pretty(lines).unwrap_or_else(|_| "[]".to_string());
    println!("{}", json_str);
}

pub fn print_csv(lines: &[LogLine]) {
    println!("date,time,remote address,method,path,status,bytes sent,referer");
    for line in lines {
        println!(
            "{},{},{},{},\"{}\",{},{},\"{}\"",
            line.date,
            line.time,
            line.remote_addr,
            line.method,
            line.path,
            line.status,
            line.bytes_sent,
            line.referer
        );
    }
}

pub fn print_raw(lines: &[LogLine]) {
    for line in lines {
        println!("{}", line.raw_line);
    }
}

pub fn print_tables(
    tables: &[TableData],
    total_unfiltered_hits: u64,
    total_unfiltered_bytes: u64,
    min_date: &str,
    max_date: &str,
    filter_summaries: &[(String, String, f64, u64, u64)],
    use_color: bool,
    key_bytes: bool,
    show_changes: bool,
) {
    let color_pink = if use_color { "\x1b[38;5;204m" } else { "" };
    let color_yellow_bold = if use_color { "\x1b[38;5;11m\x1b[1m" } else { "" };
    let color_gold = if use_color { "\x1b[38;5;178m" } else { "" };
    let reset = if use_color { "\x1b[0m" } else { "" };
    let reset_fg = if use_color { "\x1b[39m" } else { "" };

    // Summary line
    println!(
        "{}{} hits and {}{}{} from {}{}{}{} to {}{}{}{}",
        color_pink,
        fmt_num(total_unfiltered_hits),
        reset_fg,
        fmt_bytes(total_unfiltered_bytes),
        reset_fg,
        color_yellow_bold,
        min_date,
        reset,
        reset_fg,
        color_yellow_bold,
        max_date,
        reset,
        reset_fg
    );

    // Filter summaries
    if !filter_summaries.is_empty() {
        for (field, pattern, removed_pct, kept_hits, kept_bytes) in filter_summaries {
            println!(
                "Filtering by {} on pattern {} removed {:.2}%\nof total lines",
                field, pattern, removed_pct
            );
            println!(
                " ==> hits: {}, bytes sent: {}",
                fmt_num(*kept_hits),
                fmt_bytes(*kept_bytes)
            );
        }
    }

    if filter_summaries.iter().any(|(_, _, _, hits, _)| *hits == 0) {
        return;
    }

    for table in tables {
        if !table.title.is_empty() {
            println!("{}{}{}", color_gold, table.title, reset_fg);
        }

        match table.field {
            Field::Date => print_date_table(table, use_color, key_bytes),
            Field::Time => print_time_table(table, use_color, key_bytes),
            _ => print_standard_table(table, use_color, key_bytes, show_changes),
        }
    }
}

fn print_date_table(table: &TableData, use_color: bool, key_bytes: bool) {
    let color_pink = if use_color { "\x1b[38;5;204m" } else { "" };
    let color_gray = if use_color { "\x1b[38;5;239m" } else { "" };
    let color_yellow_bold = if use_color { "\x1b[38;5;11m\x1b[1m" } else { "" };
    let reset = if use_color { "\x1b[0m" } else { "" };
    let reset_fg = if use_color { "\x1b[39m" } else { "" };

    let max_val = if key_bytes { table.max_bytes } else { table.max_hits };
    let max_val_str = if key_bytes { fmt_bytes(max_val) } else { fmt_num(max_val) };

    let max_hits_width = table.rows.iter().map(|r| fmt_num(r.hits).len()).max().unwrap_or(1).max(4);
    let max_bytes_width = table.rows.iter().map(|r| fmt_bytes(r.bytes).len()).max().unwrap_or(1).max(5);

    // Top border
    println!(
        "{}┌──────────┬{}┬{}┬────────────────────┐{}",
        color_gray,
        "─".repeat(max_hits_width),
        "─".repeat(max_bytes_width),
        reset_fg
    );

    // Header
    let bar_hdr = format!("0{:>19}", max_val_str);
    let bar_hdr_pad = if bar_hdr.len() > 20 { &bar_hdr[..20] } else { &bar_hdr };
    println!(
        "{}│{}   date   {}│{}{:>width_h$}{}│{}{:>width_b$}{}│{}{:<20}{}│{}",
        color_gray,
        color_yellow_bold,
        color_gray,
        color_yellow_bold,
        "hits",
        color_gray,
        color_yellow_bold,
        "bytes",
        color_gray,
        color_yellow_bold,
        bar_hdr_pad,
        color_gray,
        reset_fg,
        width_h = max_hits_width,
        width_b = max_bytes_width,
    );

    // Mid border
    println!(
        "{}├──────────┼{}┼{}┼────────────────────┤{}",
        color_gray,
        "─".repeat(max_hits_width),
        "─".repeat(max_bytes_width),
        reset_fg
    );

    // Rows
    for row in &table.rows {
        let bar_val = if key_bytes { row.bytes } else { row.hits };
        let bar_str = render_bar(bar_val, max_val, 20);
        let hits_str = fmt_num(row.hits);
        let bytes_str = fmt_bytes(row.bytes);

        let hits_colored = if !key_bytes { format!("{}{:>width_h$}{}", color_pink, hits_str, reset_fg, width_h = max_hits_width) } else { format!("{:>width_h$}", hits_str, width_h = max_hits_width) };
        let bytes_colored = if key_bytes { format!("{}{:>width_b$}{}", color_pink, bytes_str, reset_fg, width_b = max_bytes_width) } else { format!("{:>width_b$}", bytes_str, width_b = max_bytes_width) };
        let bar_colored = format!("{}{}{}", color_pink, bar_str.trim_end(), reset_fg);
        let bar_spaces = " ".repeat(20 - bar_str.trim_end().chars().count());

        println!(
            "{}│{}{}{}│{}│{}│{}{}{}│{}",
            color_gray,
            reset_fg,
            row.value,
            color_gray,
            hits_colored,
            bytes_colored,
            bar_colored,
            bar_spaces,
            color_gray,
            reset_fg
        );
    }

    // Bottom border
    println!(
        "{}└──────────┴{}┴{}┴────────────────────┘{}",
        color_gray,
        "─".repeat(max_hits_width),
        "─".repeat(max_bytes_width),
        reset_fg
    );
}

fn print_time_table(table: &TableData, use_color: bool, key_bytes: bool) {
    let color_pink = if use_color { "\x1b[38;5;204m" } else { "" };
    let color_gray = if use_color { "\x1b[38;5;239m" } else { "" };
    let color_yellow_bold = if use_color { "\x1b[38;5;11m\x1b[1m" } else { "" };
    let reset = if use_color { "\x1b[0m" } else { "" };
    let reset_fg = if use_color { "\x1b[39m" } else { "" };

    let max_val = if key_bytes { table.max_bytes } else { table.max_hits };
