    );

    // Header
    let bar_hdr = format!("0{:>19}", max_val_str);
    let bar_hdr_pad = if bar_hdr.len() > 20 { &bar_hdr[..20] } else { &bar_hdr };
    println!(
        "{}│{}hour{}│{}{:>width_h$}{}│{}{:>width_b$}{}│{}{:<20}{}│{}",
        color_gray,
