fn render_days_bar(daily_hits: &[u64]) -> String {
    let max_d = *daily_hits.iter().max().unwrap_or(&0);
    if max_d == 0 {
        return " ".repeat(daily_hits.len());
    }
    let blocks = [" ", "▁", " ", "▃", "▄", "▅", "▆", "▇", "▇"];
    let mut s = String::new();
    for &h in daily_hits {
        if h == 0 {
            s.push(' ');
        } else {
            let frac = (h as f64) / (max_d as f64);
            let idx = (frac * 8.0).round() as usize;
            let idx = idx.clamp(1, 8);
            s.push_str(blocks[idx]);
        }
    }
    s
}
