pub fn print_tables(
    tables: &[TableData],
    total_unfiltered_hits: u64,
    total_unfiltered_bytes: u64,
    min_date: &str,
    max_date: &str,
    filter_summaries: &[(String, String, f64, u64, u64)],
    use_color: bool,
    key_bytes: bool,
    show_changes: bool,
) {
    let color_pink = if use_color { "\x1b[38;5;204m" } else { "" };
    let color_yellow_bold = if use_color { "\x1b[38;5;11m\x1b[1m" } else { "" };
    let color_gold = if use_color { "\x1b[38;5;178m" } else { "" };
    let reset = if use_color { "\x1b[0m" } else { "" };
    let reset_fg = if use_color { "\x1b[39m" } else { "" };

    // Summary line
    println!(
        "{}{} hits and {}{}{} from {}{}{}{} to {}{}{}{}",
        color_pink,
        fmt_num(total_unfiltered_hits),
        reset_fg,
        fmt_bytes(total_unfiltered_bytes),
        reset_fg,
        color_yellow_bold,
        min_date,
        reset,
        reset_fg,
        color_yellow_bold,
        max_date,
        reset,
        reset_fg
    );

    // Filter summaries
    if !filter_summaries.is_empty() {
        for (field, pattern, removed_pct, kept_hits, kept_bytes) in filter_summaries {
            println!(
                "Filtering by {} on pattern {} removed {:.2}%\nof total lines",
                field, pattern, removed_pct
            );
            println!(
                " ==> hits: {}, bytes sent: {}",
                fmt_num(*kept_hits),
                fmt_bytes(*kept_bytes)
            );
        }
    }

    if filter_summaries.iter().any(|(_, _, _, hits, _)| *hits == 0) {
        return;
    }

    for table in tables {
        if !table.title.is_empty() {
            println!("{}{}{}", color_gold, table.title, reset_fg);
        }

        match table.field {
            Field::Date => print_date_table(table, use_color, key_bytes),
            Field::Time => print_time_table(table, use_color, key_bytes),
            _ => print_standard_table(table, use_color, key_bytes, show_changes),
        }
    }
}

