                fmt_num(*kept_hits),
                fmt_bytes(*kept_bytes)
            );
        }
    }

    if filter_summaries.iter().any(|(_, _, _, hits, _)| *hits == 0) {
        return;
    }

    for table in tables {
        if !table.title.is_empty() {
            println!("{}{}{}", color_gold, table.title, reset_fg);
        }

        match table.field {
            Field::Date => print_date_table(table, use_color, key_bytes),
            Field::Time => print_time_table(table, use_color, key_bytes),
            _ => print_standard_table(table, use_color, key_bytes, show_changes),
        }
    }
}

