fn print_standard_table(table: &TableData, use_color: bool, key_bytes: bool, show_changes: bool) {
    let color_pink = if use_color { "\x1b[38;5;204m" } else { "" };
    let color_gray = if use_color { "\x1b[38;5;239m" } else { "" };
    let color_yellow_bold = if use_color { "\x1b[38;5;11m\x1b[1m" } else { "" };
    let reset_fg = if use_color { "\x1b[39m" } else { "" };

    let val_header = match table.field {
        Field::Method => "method",
        Field::Status => "status",
        Field::Ip => "IP address",
        Field::Referer => "referrer",
        Field::Path => "path",
        _ => "value",
    };

    let n_rows = table.rows.len();
    let num_col_width = format!("{}", n_rows).len().max(1) + 2; // e.g. " 1"

    let max_val_width = table.rows.iter().map(|r| r.value.len()).max().unwrap_or(0).max(val_header.len());
    let max_hits_width = table.rows.iter().map(|r| fmt_num(r.hits).len()).max().unwrap_or(1).max(4);
    let max_pct_width = table.rows.iter().map(|r| {
        let pct = if key_bytes { r.pct_bytes } else { r.pct_hits };
        format!("{:.1}%", pct).len()
    }).max().unwrap_or(1).max(5);
    let max_bytes_width = table.rows.iter().map(|r| fmt_bytes(r.bytes).len()).max().unwrap_or(1).max(5);

    let days_width = table.dates.len().max(4);

    // Top border
    if show_changes {
        println!(
            "{}┌{}┬{}┬{}┬{}┬{}┬─────┐{}",
            color_gray,
            "─".repeat(num_col_width),
            "─".repeat(max_val_width),
            "─".repeat(max_hits_width),
            "─".repeat(max_bytes_width),
            "─".repeat(days_width),
            reset_fg
        );
    } else {
        println!(
            "{}┌{}┬{}┬{}┬{}┬{}┐{}",
            color_gray,
            "─".repeat(num_col_width),
            "─".repeat(max_val_width),
            "─".repeat(max_hits_width),
            "─".repeat(max_pct_width),
            "─".repeat(max_bytes_width),
            reset_fg
        );
    }

    // Header
    if show_changes {
        println!(
            "{}│{} # {}│{}{:<width_v$}{}│{}{:>width_h$}{}│{}{:>width_b$}{}│{}{:^width_d$}{}│{}trend{}│{}",
            color_gray,
            color_yellow_bold, color_gray,
            color_yellow_bold, val_header, color_gray,
            color_yellow_bold, "hits", color_gray,
            color_yellow_bold, "bytes", color_gray,
            color_yellow_bold, "days", color_gray,
            color_yellow_bold, color_gray,
            reset_fg,
            width_v = max_val_width,
            width_h = max_hits_width,
            width_b = max_bytes_width,
            width_d = days_width,
        );
    } else {
        println!(
            "{}│{} # {}│{}{:<width_v$}{}│{}{:>width_h$}{}│{}{:>width_p$}{}│{}{:>width_b$}{}│{}",
            color_gray,
            color_yellow_bold, color_gray,
            color_yellow_bold, val_header, color_gray,
            color_yellow_bold, "hits", color_gray,
            color_yellow_bold, "%", color_gray,
            color_yellow_bold, "bytes", color_gray,
            reset_fg,
            width_v = max_val_width,
            width_h = max_hits_width,
            width_p = max_pct_width,
            width_b = max_bytes_width,
        );
    }

    // Mid border
    if show_changes {
        println!(
            "{}├{}┼{}┼{}┼{}┼{}┼─────┤{}",
            color_gray,
            "─".repeat(num_col_width),
            "─".repeat(max_val_width),
            "─".repeat(max_hits_width),
            "─".repeat(max_bytes_width),
            "─".repeat(days_width),
            reset_fg
        );
    } else {
        println!(
            "{}├{}┼{}┼{}┼{}┼{}┤{}",
            color_gray,
            "─".repeat(num_col_width),
            "─".repeat(max_val_width),
            "─".repeat(max_hits_width),
            "─".repeat(max_pct_width),
            "─".repeat(max_bytes_width),
            reset_fg
        );
    }

    // Rows
    for (idx, row) in table.rows.iter().enumerate() {
        let num_str = format!("{:>width_n$}", idx + 1, width_n = num_col_width - 1);
        let val_str = format!("{:<width_v$}", row.value, width_v = max_val_width);
        let hits_str = fmt_num(row.hits);
        let bytes_str = fmt_bytes(row.bytes);
        let pct_val = if key_bytes { row.pct_bytes } else { row.pct_hits };
        let pct_str = format!("{:.1}%", pct_val);

        let hits_colored = if !key_bytes { format!("{}{:>width_h$}{}", color_pink, hits_str, reset_fg, width_h = max_hits_width) } else { format!("{:>width_h$}", hits_str, width_h = max_hits_width) };
        let bytes_colored = if key_bytes { format!("{}{:>width_b$}{}", color_pink, bytes_str, reset_fg, width_b = max_bytes_width) } else { format!("{:>width_b$}", bytes_str, width_b = max_bytes_width) };

        if show_changes {
            let days_str = render_days_bar(&row.daily_hits);
            let trend_str = format!("{:^5}", row.trend);

            println!(
                "{}│{} {}│{}│{}│{}│{}│{}│{}",
                color_gray,
                num_str,
                color_gray,
                val_str,
                hits_colored,
                bytes_colored,
                days_str,
                trend_str,
                color_gray,
            );
        } else {
            println!(
                "{}│{} {}│{}│{}│{:>width_p$}│{}│{}",
                color_gray,
                num_str,
                color_gray,
                val_str,
                hits_colored,
                pct_str,
                bytes_colored,
                color_gray,
                width_p = max_pct_width,
            );
        }
    }

    // Bottom border
    if show_changes {
        println!(
            "{}└{}┴{}┴{}┴{}┴{}┴─────┘{}",
            color_gray,
            "─".repeat(num_col_width),
            "─".repeat(max_val_width),
            "─".repeat(max_hits_width),
            "─".repeat(max_bytes_width),
            "─".repeat(days_width),
            reset_fg
        );
    } else {
        println!(
            "{}└{}┴{}┴{}┴{}┴{}┘{}",
            color_gray,
            "─".repeat(num_col_width),
            "─".repeat(max_val_width),
            "─".repeat(max_hits_width),
            "─".repeat(max_pct_width),
            "─".repeat(max_bytes_width),
            reset_fg
        );
    }
}

fn render_days_bar(daily_hits: &[u64]) -> String {
    let max_d = *daily_hits.iter().max().unwrap_or(&0);
    if max_d == 0 {
        return " ".repeat(daily_hits.len());
    }
    let blocks = [" ", "▁", " ", "▃", "▄", "▅", "▆", "▇", "▇"];
    let mut s = String::new();
    for &h in daily_hits {
        if h == 0 {
            s.push(' ');
        } else {
            let frac = (h as f64) / (max_d as f64);
            let idx = (frac * 8.0).round() as usize;
            let idx = idx.clamp(1, 8);
            s.push_str(blocks[idx]);
        }
    }
    s
}
