use std::collections::HashMap;
use crate::log_line::LogLine;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Field {
    Date,
    Time,
    Method,
    Status,
    Ip,
    Referer,
    Path,
}

pub fn parse_fields(s: Option<&str>) -> Vec<Field> {
    let default_fields = vec![Field::Date, Field::Status, Field::Referer, Field::Path];
    let all_fields = vec![
        Field::Date, Field::Time, Field::Method, Field::Status, Field::Ip, Field::Referer, Field::Path
    ];

    let s = match s {
        Some(val) => val.trim(),
        None => return default_fields,
    };

    if s.is_empty() {
        return default_fields;
    }

    let starts_with_modifier = s.starts_with('+') || s.starts_with('-');
    let mut current = if starts_with_modifier {
        default_fields
    } else {
        Vec::new()
    };

    // Parse tokens split by comma or plus or minus
    let mut tokens = Vec::new();
    let mut cur_token = String::new();
    let mut cur_op = '+';

    for c in s.chars() {
        if c == ',' || c == '+' || c == '-' {
            if !cur_token.is_empty() {
                tokens.push((cur_op, cur_token.clone()));
                cur_token.clear();
            }
            if c == '+' || c == '-' {
                cur_op = c;
            } else {
                cur_op = '+';
            }
        } else {
            cur_token.push(c);
        }
    }
    if !cur_token.is_empty() {
        tokens.push((cur_op, cur_token));
    }

    if !starts_with_modifier && !tokens.is_empty() {
        let first = &tokens[0].1;
        if first == "all" || first == "a" {
            current = all_fields;
            tokens.remove(0);
        }
    }

    for (op, token) in tokens {
        let field = match token.as_str() {
            "date" | "d" => Some(Field::Date),
            "time" | "t" => Some(Field::Time),
            "method" | "m" => Some(Field::Method),
            "status" | "s" => Some(Field::Status),
            "ip" | "i" => Some(Field::Ip),
            "ref" | "referer" | "r" => Some(Field::Referer),
            "path" | "p" => Some(Field::Path),
            "all" | "a" => None, // Handled if first
            _ => {
                // Unknown token! If starts with valid prefix:
                if token.starts_with('d') { Some(Field::Date) }
                else if token.starts_with('t') { Some(Field::Time) }
                else if token.starts_with('m') { Some(Field::Method) }
                else if token.starts_with('s') { Some(Field::Status) }
                else if token.starts_with('i') { Some(Field::Ip) }
                else if token.starts_with('r') { Some(Field::Referer) }
                else if token.starts_with('p') { Some(Field::Path) }
                else if token.starts_with('a') { None }
                else {
                    return Vec::new(); // Invalid token -> empty
                }
            }
        };

        if let Some(f) = field {
            if op == '+' {
                if let Some(pos) = current.iter().position(|&x| x == f) {
                    current.remove(pos);
                }
                current.push(f);
            } else if op == '-' {
                if let Some(pos) = current.iter().position(|&x| x == f) {
                    current.remove(pos);
                }
            }
        }
    }

    current
}

#[derive(Debug, Clone)]
pub struct TableRow {
    pub value: String,
    pub hits: u64,
    pub bytes: u64,
    pub pct_hits: f64,
    pub pct_bytes: f64,
    pub daily_hits: Vec<u64>,
    pub trend: String,
}

#[derive(Debug, Clone)]
pub struct TableData {
    pub field: Field,
    pub title: String,
    pub rows: Vec<TableRow>,
    pub max_hits: u64,
    pub max_bytes: u64,
    pub dates: Vec<String>,
}

pub fn build_table(
    field: Field,
    lines: &[LogLine],
    all_dates: &[String],
    key_bytes: bool,
    length_level: usize,
    show_changes: bool,
    show_all: bool,
) -> TableData {
    let mut map: HashMap<String, (u64, u64, Vec<u64>)> = HashMap::new();
    let date_to_idx: HashMap<&str, usize> = all_dates.iter().enumerate().map(|(i, d)| (d.as_str(), i)).collect();

    let mut filtered_lines: Vec<&LogLine> = Vec::new();
    for line in lines {
        if field == Field::Path && !show_all && line.is_resource {
            continue;
        }
        filtered_lines.push(line);
    }

    for line in &filtered_lines {
        let val = match field {
            Field::Date => line.date.clone(),
            Field::Time => format!("{:02}", line.time.split(':').next().unwrap_or("00").parse::<u32>().unwrap_or(0)),
            Field::Method => line.method.clone(),
            Field::Status => line.status.clone(),
            Field::Ip => line.remote_addr.clone(),
            Field::Referer => line.referer.clone(),
            Field::Path => line.path.clone(),
        };

        let entry = map.entry(val).or_insert((0, 0, vec![0; all_dates.len()]));
        entry.0 += 1;
        entry.1 += line.bytes_sent;
        if let Some(&idx) = date_to_idx.get(line.date.as_str()) {
            if idx < entry.2.len() {
                entry.2[idx] += 1;
            }
        }
    }

    let total_hits: u64 = filtered_lines.iter().map(|_l| 1).sum();
    let total_bytes: u64 = filtered_lines.iter().map(|l| l.bytes_sent).sum();

    let mut max_hits = 0;
    let mut max_bytes = 0;

    // Period calculations for trend
    let n_dates = all_dates.len();
    let (period1_range, period2_range) = if n_dates >= 4 {
        ((n_dates - 4)..=(n_dates - 3), (n_dates - 2)..=(n_dates - 1))
    } else {
        (0..=0, 0..=0)
    };

    let total_p1_hits: u64 = if n_dates >= 4 {
        all_dates[period1_range.clone()].iter().map(|d| {
            filtered_lines.iter().filter(|l| l.date == *d).count() as u64
        }).sum()
    } else { 0 };

    let total_p2_hits: u64 = if n_dates >= 4 {
        all_dates[period2_range.clone()].iter().map(|d| {
            filtered_lines.iter().filter(|l| l.date == *d).count() as u64
        }).sum()
    } else { 0 };

    let mut rows = Vec::new();

    if field == Field::Time {
        // Hour 0..23
        for h in 0..24 {
            let val = format!("{:02}", h);
            let (hits, bytes, daily) = map.get(&val).cloned().unwrap_or((0, 0, vec![0; all_dates.len()]));
            if hits > max_hits { max_hits = hits; }
            if bytes > max_bytes { max_bytes = bytes; }
            rows.push(TableRow {
                value: val,
                hits,
                bytes,
                pct_hits: if total_hits > 0 { hits as f64 / total_hits as f64 * 100.0 } else { 0.0 },
                pct_bytes: if total_bytes > 0 { bytes as f64 / total_bytes as f64 * 100.0 } else { 0.0 },
                daily_hits: daily,
                trend: String::new(),
            });
        }
    } else if field == Field::Date {
        for d in all_dates {
            let (hits, bytes, daily) = map.get(d).cloned().unwrap_or((0, 0, vec![0; all_dates.len()]));
            if hits > max_hits { max_hits = hits; }
            if bytes > max_bytes { max_bytes = bytes; }
            rows.push(TableRow {
                value: d.clone(),
                hits,
                bytes,
                pct_hits: if total_hits > 0 { hits as f64 / total_hits as f64 * 100.0 } else { 0.0 },
                pct_bytes: if total_bytes > 0 { bytes as f64 / total_bytes as f64 * 100.0 } else { 0.0 },
                daily_hits: daily,
                trend: String::new(),
            });
        }
    } else {
        for (val, (hits, bytes, daily)) in map {
            if hits > max_hits { max_hits = hits; }
            if bytes > max_bytes { max_bytes = bytes; }

            let mut trend = String::new();

            if show_changes && n_dates >= 4 && total_p1_hits > 0 && total_p2_hits > 0 {
                let p1_hits: u64 = period1_range.clone().map(|idx| daily[idx]).sum();
                let p2_hits: u64 = period2_range.clone().map(|idx| daily[idx]).sum();

